const places = $input.item.json.places || [];
const region = $('Set Regional Search Query').item.json.region || 'Greece';
const output = [];

for (const p of places) {
  let rawPhone = p.phoneNumber || '';
  let cleanPhone = rawPhone.replace(/[^0-9+]/g, '');

  // Normalize Greek numbers
  if (cleanPhone.startsWith('69') && cleanPhone.length === 10) {
    cleanPhone = '+30' + cleanPhone;
  } else if (cleanPhone.startsWith('30') && !cleanPhone.startsWith('+')) {
    cleanPhone = '+' + cleanPhone;
  }

  // Skip OTA platforms
  let website = p.website || '';
  if (website.includes('booking.com') || website.includes('airbnb.') || website.includes('tripadvisor.')) {
    website = '';
  }

  output.push({
    json: {
      property_name: p.title || 'Greek Villa',
      phone: cleanPhone || rawPhone,
      raw_phone: rawPhone,
      website: website,
      address: p.address || '',
      rating: p.rating || 4.8,
      reviews_count: p.ratingCount || 10,
      category: p.category || 'Vacation rental',
      region: region
    }
  });
}

return output.slice(0, 5);

let raw = $input.item.json.message?.content || $input.item.json.response || $input.item.json || {};
if (typeof raw === 'string') {
  raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
  try {
    raw = JSON.parse(raw);
  } catch(e) {}
}
return { json: raw };
